mapper.select:
SELECT um.id, um.message_id AS messageId, um.read_flag AS readFlag, um.created_at AS createdAt, m.title, m.category, m.content FROM sys_user_message um INNER JOIN sys_message m ON um.message_id = m.id WHERE um.user_id = #{userId} AND m.enabled = 1
AND (m.title LIKE CONCAT('%', #{blurry}, '%') OR m.content LIKE CONCAT('%', #{blurry}, '%'))
AND um.created_at >= #{createTime[0]}
AND um.created_at <= #{createTime[1]}
ORDER BY m.seq DESC, um.created_at DESC
